/// Bytes-in → snapshot-out. Does not write the snapshot, set root/heads, or append an op.
/// `files` is the whole tree; `prev` lends ids only. Names resolve against what is parsed
/// here — never against `prev`, whose entities may be exactly what this edit deleted (a
/// reference kept bound to a gone id renders as `?`).
pub fn snapshot_files(
    store: &dyn Store,
    langs: &Langs,
    files: &BTreeMap<RelPath, Vec<u8>>,
    prev: Option<&Snapshot>,
    change: ChangeId,
) -> Result<Snapshot> {
    snapshot_files_reusing(store, langs, files, prev, change, &std::collections::BTreeSet::new())
}

/// [`snapshot_files`] where `unchanged` names files whose bytes are exactly what `prev`
/// rendered for them. Parsing is cheap; `materialize` (the canonical stream, resolved
/// against the whole tree's names) is what an absorb of one file pays for every file.
/// When the tree's definitions — name, kind, id, parent, file — are the same set as
/// `prev`'s, the names resolve exactly as they did, so an unchanged file's records are
/// `prev`'s records: same content, same bytes, same ids. Any new, gone, renamed or moved
/// definition anywhere re-materializes everything, as before.
pub fn snapshot_files_reusing(
    store: &dyn Store,
    langs: &Langs,
    files: &BTreeMap<RelPath, Vec<u8>>,
    prev: Option<&Snapshot>,
    change: ChangeId,
    unchanged: &std::collections::BTreeSet<RelPath>,
) -> Result<Snapshot> {
    struct Parsed<'a> {
        path: RelPath,
        src: &'a [u8],
        tree: tree_sitter::Tree,
        raw: Vec<RawEntity>,
        lang: &'a dyn Lang,
        ids: Vec<EntityId>,
    }
    let mut parsed = Vec::new();
    let mut opaque = BTreeMap::new();
    let mut prev_ids = prev_ids(prev);
    for (path, src) in files {
        match langs.for_path(path) {
            Some(lang) => {
                let tree = parse(src, lang)?;
                let raw = extract(&tree, src, lang)?;
                let ids = assign_ids(&raw, path, &mut prev_ids, prev);
                parsed.push(Parsed {
                    path: path.clone(),
                    src,
                    tree,
                    raw,
                    lang,
                    ids,
                });
            }
            // Manifests, lockfiles, recordings: stored as the file tail with no
            // entities so `svc init` on this repo still renders a tree cargo can build.
            None => {
                opaque.insert(path.clone(), src.clone());
            }
        }
    }
    // Prev is for assign_ids. Seeding names from it keeps deleted same-file
    // defs in the env, so a remaining call binds to a missing id and render
    // prints `?` (claude 03:34: absorb after deleting resolve_entity_in).
    let mut env = Env::default();
    for p in &parsed {
        for (i, ent) in p.raw.iter().enumerate() {
            insert_mod_child_raw(&mut env, &p.raw, &p.ids, i);
            if is_inherent_raw(&p.raw, i) || is_block_local_raw(&p.raw, i) {
                continue;
            }
            env.insert_def_in(&ent.name, ent.kind, p.ids[i], Some(&p.path));
        }
    }
    {
        let views: Vec<(&RelPath, &[RawEntity], &[EntityId])> = parsed
            .iter()
            .map(|p| (&p.path, p.raw.as_slice(), p.ids.as_slice()))
            .collect();
        link_file_modules(&mut env, &views);
    }
    // The definitions this tree declares, as `prev` would list them; equal sets mean an
    // identical name environment.
    let reuse = match prev {
        Some(prev) if !unchanged.is_empty() => {
            let mut now: Vec<(&RelPath, &str, Kind, EntityId, Option<EntityId>)> = parsed
                .iter()
                .flat_map(|p| {
                    p.raw.iter().enumerate().map(move |(i, ent)| {
                        (&p.path, ent.name.as_str(), ent.kind, p.ids[i], ent.parent_idx.map(|pi| p.ids[pi]))
                    })
                })
                .collect();
            let mut before: Vec<(&RelPath, &str, Kind, EntityId, Option<EntityId>)> = prev
                .entities
                .iter()
                .map(|(id, rec)| (&rec.file, rec.name.as_str(), rec.kind, *id, rec.parent))
                .collect();
            now.sort();
            before.sort();
            now == before
        }
        _ => false,
    };
    let mut entities = BTreeMap::new();
    let mut file_recs = BTreeMap::new();
    for p in &parsed {
        if reuse && unchanged.contains(&p.path) {
            if let Some(prev) = prev
                && let Some(file) = prev.files.get(&p.path)
            {
                entities.extend(prev.entities.iter().filter(|(_, r)| r.file == p.path).map(|(id, r)| (*id, r.clone())));
                file_recs.insert(p.path.clone(), file.clone());
                continue;
            }
        }
        let (ents, file) = materialize(
            p.src,
            p.path.clone(),
            p.lang,
            store,
            &p.tree,
            &p.raw,
            &p.ids,
            &env,
        )?;
        entities.extend(ents);
        file_recs.insert(p.path.clone(), file);
    }
    for (path, src) in opaque {
        file_recs.insert(path, FileRecord::from_tail(store, &src)?);
    }
    Ok(Snapshot {
        parents: Vec::new(),
        predecessors: Vec::new(),
        change,
        entities,
        files: file_recs,
        conflicts: Vec::new(),
        message: String::new(),
    })
}

pub fn ingest_file(
    src: &[u8],
    path: RelPath,
    lang: &dyn Lang,
    store: &dyn Store,
    change: ChangeId,
) -> Result<Snapshot> {
    ingest_file_with_env(src, path, lang, store, change, &Env::default())
}

pub fn ingest_file_with_env(
    src: &[u8],
    path: RelPath,
    lang: &dyn Lang,
    store: &dyn Store,
    change: ChangeId,
    extra: &Env,
) -> Result<Snapshot> {
    ingest_file_prev(src, path, lang, store, change, None, extra)
}

pub fn ingest_file_prev(
    src: &[u8],
    path: RelPath,
    lang: &dyn Lang,
    store: &dyn Store,
    change: ChangeId,
    prev: Option<&Snapshot>,
    extra: &Env,
) -> Result<Snapshot> {
    let tree = parse(src, lang)?;
    let raw = extract(&tree, src, lang)?;
    let ids = assign_ids(&raw, &path, &mut prev_ids(prev), prev);
    let mut env = extra.clone();
    for (i, ent) in raw.iter().enumerate() {
        insert_mod_child_raw(&mut env, &raw, &ids, i);
        if is_inherent_raw(&raw, i) || is_block_local_raw(&raw, i) {
            continue;
        }
        env.insert_def_in(&ent.name, ent.kind, ids[i], Some(&path));
    }
    link_file_modules_from_raw(&mut env, &path, &raw, &ids);
    let (entities, file) = materialize(src, path.clone(), lang, store, &tree, &raw, &ids, &env)?;
    let mut files = BTreeMap::new();
    files.insert(path, file);
    Ok(Snapshot {
        parents: Vec::new(),
        predecessors: Vec::new(),
        change,
        entities,
        files,
        conflicts: Vec::new(),
        message: String::new(),
    })
}

fn materialize(
    src: &[u8],
    path: RelPath,
    lang: &dyn Lang,
    store: &dyn Store,
    tree: &tree_sitter::Tree,
    raw: &[RawEntity],
    ids: &[EntityId],
    env: &Env,
) -> Result<(BTreeMap<EntityId, EntityRecord>, FileRecord)> {
    let mut entities = BTreeMap::new();
    // Clone once per file: `Env.names` is Arc, so this is not O(n) in the snapshot.
    // Filling `self_methods` only when the caller left it empty — `edit_def` fills it
    // from the snapshot, and the fragment being parsed has no siblings (opus 03:05).
    let mut local_env = env.clone();
    local_env.current_file = Some(path.clone());
    let caller_supplied = !env.self_methods.is_empty();
    let mut sibs: std::collections::HashMap<usize, std::collections::HashMap<String, EntityId>> =
        std::collections::HashMap::new();
    if !caller_supplied {
        for (j, sib) in raw.iter().enumerate() {
            if let Some(p) = sib.parent_idx {
                if is_callable_member(sib.kind) {
                    sibs.entry(p).or_default().insert(sib.name.clone(), ids[j]);
                }
            }
        }
    }
    for (i, ent) in raw.iter().enumerate() {
        let node = extract::find_node(tree.root_node(), ent.item_range)
            .ok_or_else(|| Error::Parse(format!("no node for {}", ent.name)))?;
        if !caller_supplied {
            local_env.self_methods = ent
                .parent_idx
                .and_then(|p| sibs.get(&p))
                .cloned()
                .unwrap_or_default();
        }
        fill_nested_items_from_raw(&mut local_env, raw, ids, i);
        fill_mod_env_from_raw(&mut local_env, raw, ids, i);
        let res = resolve(node, src, lang, &local_env)?;
        let children: Vec<(ByteRange, EntityId)> = ent
            .children
            .iter()
            .map(|&c| (raw[c].bytes_range, ids[c]))
            .collect();
        let own_name = ent.name_range.map(|r| (r, EntityId::SELF));
        let bytes = bytes::bytes_from_span(src, ent.bytes_range, &children, own_name, &res, node)?;
        let bytes_id = store.put_bytes_blob(&bytes)?;
        let child_spans: Vec<(ByteRange, EntityId)> = ent
            .children
            .iter()
            .map(|&c| (raw[c].item_range, ids[c]))
            .collect();
        let content = canonicalize(node, src, &res, &child_spans, &local_env, lang)?;
        let content_id = store.put_content(&content)?;
        let ordinal = raw
            .iter()
            .filter(|o| o.parent_idx == ent.parent_idx && o.item_range.start < ent.item_range.start)
            .count() as u32;
        entities.insert(
            ids[i],
            EntityRecord {
                name: ent.name.clone(),
                kind: ent.kind,
                parent: ent.parent_idx.map(|p| ids[p]),
                file: path.clone(),
                ordinal,
                content: content_id,
                bytes: bytes_id,
            },
        );
    }
    let roots: Vec<_> = raw
        .iter()
        .filter(|e| e.parent_idx.is_none())
        .cloned()
        .collect();
    let trailing = render_impl::trailing_for(src, &roots);
    Ok((entities, FileRecord::from_tail(store, &trailing)?))
}

/// Reuse ids from `prev` by SigKey: nested items match under their parent, file-level
/// items only within `file` (two files may each define `fn hex32`).
/// The previous snapshot's ids by signature, each list in id order: a re-ingested entity
/// keeps its id, and two same-signature entities take theirs in the order they had.
/// Built once per ingest; a lookup per raw entity instead of a scan of every record.
type PrevIds = BTreeMap<SigKey, std::collections::VecDeque<EntityId>>;

fn prev_ids(prev: Option<&Snapshot>) -> PrevIds {
    let mut by_sig = PrevIds::new();
    if let Some(prev) = prev {
        for (id, rec) in &prev.entities {
            by_sig.entry(rec.sig_key()).or_default().push_back(*id);
        }
    }
    by_sig
}

fn assign_ids(
    raw: &[RawEntity],
    file: &RelPath,
    prev: &mut PrevIds,
    snap: Option<&Snapshot>,
) -> Vec<EntityId> {
    let mut assigned: Vec<Option<EntityId>> = vec![None; raw.len()];
    let mut used = HashSet::new();
    for (i, ent) in raw.iter().enumerate() {
        let parent = match ent.parent_idx {
            Some(p) => match assigned[p] {
                Some(id) => Some(id),
                None => continue,
            },
            None => None,
        };
        let key = SigKey::new(parent, file, ent.kind, ent.name.clone());
        if let Some(id) = prev.get_mut(&key).and_then(|same| same.pop_front()) {
            assigned[i] = Some(id);
            used.insert(id);
        }
    }
    // A `use` line's name is its text. Rename of an imported fn (or a hand
    // edit of the path) changes that spelling, so SigKey misses and the line
    // used to mint a new id. Reuse an unused Opaque in this file whose text
    // still shares most of its prefix (`use crate::a::f` → `use crate::a::f2`).
    if let Some(snap) = snap {
        let leftover: Vec<(u32, EntityId, String)> = snap
            .entities
            .iter()
            .filter(|(id, rec)| rec.file == *file && rec.kind == Kind::Opaque && !used.contains(id))
            .map(|(id, rec)| (rec.ordinal, *id, rec.name.clone()))
            .collect();
        for (i, ent) in raw.iter().enumerate() {
            if assigned[i].is_some() || ent.kind != Kind::Opaque {
                continue;
            }
            let mut best: Option<(usize, u32, EntityId)> = None;
            for (ord, id, name) in &leftover {
                if used.contains(id) {
                    continue;
                }
                let n = lcp(&ent.name, name);
                if n * 2 < ent.name.len().min(name.len()) {
                    continue;
                }
                match best {
                    Some((bn, bord, _)) if (n, std::cmp::Reverse(*ord)) < (bn, std::cmp::Reverse(bord)) => {}
                    _ => best = Some((n, *ord, *id)),
                }
            }
            if let Some((_, _, id)) = best {
                assigned[i] = Some(id);
                used.insert(id);
            }
        }
    }
    assigned
        .into_iter()
        .map(|id| id.unwrap_or_else(EntityId::new))
        .collect()
}

fn lcp(a: &str, b: &str) -> usize {
    a.bytes()
        .zip(b.bytes())
        .take_while(|(x, y)| x == y)
        .count()
}

crates/svc-core/src/lang.rs.Text:
use std::collections::{HashMap, HashSet};
use std::sync::Arc;

use crate::content::Namespace;
use crate::entity::Kind;
use crate::ids::{ByteRange, EntityId, RelPath};

#[derive(Clone, Debug, Default)]
pub struct Env {
    pub names: Arc<HashMap<(String, Namespace), EntityId>>,
    /// File-root and nested defs keyed by the file they live in. A same-file
    /// `fn hex32` beats a same-named item in another crate when resolving.
    pub by_file: Arc<HashMap<RelPath, HashMap<(String, Namespace), EntityId>>>,
    /// Same-named items in `crates/<pkg>/**` share this map. File wins, then a
    /// name unique in the crate, then a name unique in the repo; collisions are Free.
    pub by_crate: Arc<HashMap<String, HashMap<(String, Namespace), EntityId>>>,
    /// Crate-level names that appear in more than one file. A third file must not
    /// bind last-wins (DOGFOOD: two file-level items with one name in one crate).
    pub crate_ambiguous: Arc<HashMap<String, HashSet<(String, Namespace)>>>,
    /// Repo-wide names that appear under more than one definition.
    pub names_ambiguous: Arc<HashSet<(String, Namespace)>>,
    /// Occupants that own this (name, ns) as their primary namespace (`fn` in
    /// Value, not `struct` which also sits in Value as a constructor).
    pub primary: Arc<HashSet<(String, Namespace)>>,
    /// Per-crate primary occupants; same rule as [`Self::primary`].
    pub crate_primary: Arc<HashMap<String, HashSet<(String, Namespace)>>>,
    /// Inherent methods and associated consts of the impl/class this item is
    /// being resolved in. `self.foo()` / `Self::foo` / `Self::N` / `this.foo()`
    /// look here, not in `names` (a free `fn foo` is a different target).
    pub self_methods: HashMap<String, EntityId>,
    /// Items nested in the function (or JS function/method) being resolved —
    /// `fn f() { fn g() {} g(); }`. They are not in [`Self::by_file`]: a sibling
    /// `fn h() { g(); }` must not bind to `f`'s helper, and a nested `fn parse`
    /// must not make a file-level `parse` in the same crate look ambiguous.
    pub nested_items: HashMap<(String, Namespace), EntityId>,
    /// When set, [`Self::lookup`] prefers [`Self::by_file`] for this path.
    pub current_file: Option<RelPath>,
    /// Inside `mod inner { … }`, bare names are the module's own items only.
    /// `crate::` still uses [`Self::lookup_module`].
    pub in_nested_mod: bool,
    /// Parent-mod maps for `super::` / `super::super::` / … Index 0 is one
    /// `super` (the parent of the enclosing mod). Past the last nested mod,
    /// [`Self::lookup_super`] falls through to [`Self::lookup_module`].
    pub super_stack: Vec<HashMap<(String, Namespace), EntityId>>,
    /// Children of each `mod` entity, for `crate::outer::parse` / `super::inner::f`.
    pub mod_items: HashMap<EntityId, HashMap<(String, Namespace), EntityId>>,
    /// Enclosing `mod` entity, for `self::inner::f`.
    pub self_mod: Option<EntityId>,
    /// File loaded by `mod foo;` → that `mod` entity. Items in the file are
    /// inside the module, not the crate root.
    pub file_of_mod: HashMap<RelPath, EntityId>,
}

impl Env {
    pub fn lookup(&self, name: &str, ns: Namespace) -> Option<EntityId> {
        if let Some(id) = Self::lookup_in_map(Some(&self.nested_items), name, ns) {
            return Some(id);
        }
        if let Some(m) = self.self_mod {
            if let Some(id) = Self::lookup_in_map(self.mod_items.get(&m), name, ns) {
                return Some(id);
            }
        }
        if self.in_nested_mod {
            return None;
        }
        self.lookup_module(name, ns)
    }

    /// `super::f` (`depth` 1) / `super::super::f` (`depth` 2). Past the last
    /// nested parent module, this is the crate root.
    pub fn lookup_super(&self, name: &str, ns: Namespace, depth: usize) -> Option<EntityId> {
        if depth == 0 {
            return None;
        }
        let i = depth - 1;
        if let Some(map) = self.super_stack.get(i) {
            return Self::lookup_in_map(Some(map), name, ns);
        }
        self.lookup_module(name, ns)
    }

    /// `crate::a::b` — `a` is crate-root, then each segment is a child of that mod.
    pub fn lookup_crate_path(&self, segs: &[String], ns: Namespace) -> Option<EntityId> {
        if segs.is_empty() {
            return None;
        }
        if segs.len() == 1 {
            return self.lookup_module(&segs[0], ns);
        }
        let start = self.lookup_module(&segs[0], Namespace::Type)?;
        self.walk_mod_path(start, &segs[1..], ns)
    }

    /// `super::a::b` after `depth` `super::` prefixes.
    pub fn lookup_super_path(
        &self,
        depth: usize,
        segs: &[String],
        ns: Namespace,
    ) -> Option<EntityId> {
        if segs.is_empty() {
            return None;
        }
        if segs.len() == 1 {
            return self.lookup_super(&segs[0], ns, depth);
        }
        let start = self.lookup_super(&segs[0], Namespace::Type, depth)?;
        self.walk_mod_path(start, &segs[1..], ns)
    }

    /// `self::a::b` in the enclosing module.
    pub fn lookup_self_path(&self, segs: &[String], ns: Namespace) -> Option<EntityId> {
        if segs.is_empty() {
            return None;
        }
        let start_mod = self.self_mod?;
        if segs.len() == 1 {
            return Self::lookup_in_map(self.mod_items.get(&start_mod), &segs[0], ns);
        }
        let start = Self::lookup_in_map(self.mod_items.get(&start_mod), &segs[0], Namespace::Type)?;
        self.walk_mod_path(start, &segs[1..], ns)
    }

    fn walk_mod_path(&self, start: EntityId, rest: &[String], ns: Namespace) -> Option<EntityId> {
        if rest.is_empty() {
            return Some(start);
        }
        let mut id = start;
        for s in &rest[..rest.len() - 1] {
            id = Self::lookup_in_map(self.mod_items.get(&id), s, Namespace::Type)?;
        }
        Self::lookup_in_map(self.mod_items.get(&id), rest.last()?, ns)
    }

    /// File / crate / repo names, skipping nested-mod isolation. `crate::f`
    /// inside `mod inner` still binds the crate-root item.
    pub fn lookup_module(&self, name: &str, ns: Namespace) -> Option<EntityId> {
        if let Some(file) = &self.current_file {
            if let Some(id) = Self::lookup_in_map(self.by_file.get(file), name, ns) {
                return Some(id);
            }
            if let Some(krate) = crate_key(file) {
                if !self
                    .crate_ambiguous
                    .get(krate)
                    .is_some_and(|s| Self::is_ambiguous(s, name, ns))
                {
                    if let Some(id) = Self::lookup_in_map(self.by_crate.get(krate), name, ns) {
                        return Some(id);
                    }
                }
            }
        }
        self.lookup_global(name, ns)
    }

    pub fn lookup_global(&self, name: &str, ns: Namespace) -> Option<EntityId> {
        if Self::is_ambiguous(&self.names_ambiguous, name, ns) {
            return None;
        }
        Self::lookup_in_map(Some(self.names.as_ref()), name, ns)
    }

    fn is_ambiguous(set: &HashSet<(String, Namespace)>, name: &str, ns: Namespace) -> bool {
        set.contains(&(name.to_string(), ns))
            || set.contains(&(name.to_string(), Namespace::Any))
    }

    fn lookup_in_map(
        map: Option<&HashMap<(String, Namespace), EntityId>>,
        name: &str,
        ns: Namespace,
    ) -> Option<EntityId> {
        let map = map?;
        map.get(&(name.to_string(), ns))
            .copied()
            .or_else(|| map.get(&(name.to_string(), Namespace::Any)).copied())
    }

    pub fn insert(&mut self, name: impl Into<String>, ns: Namespace, id: EntityId) {
        self.insert_ranked(name, ns, id, false);
    }

    fn insert_ranked(
        &mut self,
        name: impl Into<String>,
        ns: Namespace,
        id: EntityId,
        primary: bool,
    ) {
        let name = name.into();
        Self::occupy(
            Arc::make_mut(&mut self.names),
            Arc::make_mut(&mut self.names_ambiguous),
            Arc::make_mut(&mut self.primary),
            &name,
            ns,
            id,
            primary,
        );
    }

    /// Two primaries (`fn parse` in two files) or two secondaries are
    /// ambiguous. A primary may replace a secondary (`fn Foo` after
    /// `struct Foo`) without last-wins Free — they share a spelling, not a
    /// namespace.
    fn occupy(
        map: &mut HashMap<(String, Namespace), EntityId>,
        amb: &mut HashSet<(String, Namespace)>,
        primaries: &mut HashSet<(String, Namespace)>,
        name: &str,
        ns: Namespace,
        id: EntityId,
        primary: bool,
    ) {
        let key = (name.to_string(), ns);
        if let Some(old) = map.get(&key) {
            if *old != id {
                let old_primary = primaries.contains(&key);
                if old_primary && !primary {
                    return;
                }
                if old_primary == primary {
                    amb.insert(key.clone());
                }
            }
        }
        map.insert(key.clone(), id);
        if primary {
            primaries.insert(key);
        }
    }

    pub fn insert_def(&mut self, name: impl Into<String>, kind: Kind, id: EntityId) {
        self.insert_def_in(name, kind, id, None);
    }

    pub fn insert_def_in(
        &mut self,
        name: impl Into<String>,
        kind: Kind,
        id: EntityId,
        file: Option<&RelPath>,
    ) {
        let name = name.into();
        for ns in namespaces_for(kind) {
            if *ns == Namespace::Value
                && !is_value_primary(kind)
                && self.lookup_global(&name, Namespace::Value).is_some()
            {
                continue;
            }
            let primary = is_value_primary(kind) && *ns == Namespace::Value;
            self.insert_ranked(&name, *ns, id, primary);
            if let Some(file) = file {
                Arc::make_mut(&mut self.by_file)
                    .entry(file.clone())
                    .or_default()
                    .insert((name.clone(), *ns), id);
                if let Some(krate) = crate_key(file) {
                    self.insert_crate(krate, &name, *ns, id, primary);
                }
            }
        }
        if is_value_primary(kind) {
            self.insert_ranked(&name, Namespace::Value, id, true);
            if let Some(file) = file {
                Arc::make_mut(&mut self.by_file)
                    .entry(file.clone())
                    .or_default()
                    .insert((name.clone(), Namespace::Value), id);
                if let Some(krate) = crate_key(file) {
                    self.insert_crate(krate, &name, Namespace::Value, id, true);
                }
            }
        }
    }

    fn insert_crate(
        &mut self,
        krate: &str,
        name: &str,
        ns: Namespace,
        id: EntityId,
        primary: bool,
    ) {
        Self::occupy(
            Arc::make_mut(&mut self.by_crate)
                .entry(krate.to_string())
                .or_default(),
            Arc::make_mut(&mut self.crate_ambiguous)
                .entry(krate.to_string())
                .or_default(),
            Arc::make_mut(&mut self.crate_primary)
                .entry(krate.to_string())
                .or_default(),
            name,
            ns,
            id,
            primary,
        );
    }

    pub fn insert_defs(&mut self, defs: &[(&str, Kind, EntityId)]) {
        for (name, kind, id) in defs {
            self.insert_def(*name, *kind, *id);
        }
    }

    /// Bind a nested item for the duration of one `resolve`. Last insert wins
    /// so an inner function's helper shadows one on an enclosing function.
    pub fn insert_nested(&mut self, name: impl Into<String>, kind: Kind, id: EntityId) {
        let name = name.into();
        for ns in namespaces_for(kind) {
            self.nested_items.insert((name.clone(), *ns), id);
        }
    }

    pub fn insert_mod_child(
        &mut self,
        parent: EntityId,
        name: impl Into<String>,
        kind: Kind,
        id: EntityId,
    ) {
        let map = self.mod_items.entry(parent).or_default();
        Self::insert_super_level(map, name, kind, id);
    }

    pub fn insert_super_level(
        map: &mut HashMap<(String, Namespace), EntityId>,
        name: impl Into<String>,
        kind: Kind,
        id: EntityId,
    ) {
        let name = name.into();
        for ns in namespaces_for(kind) {
            map.insert((name.clone(), *ns), id);
        }
    }
}

pub fn namespaces_for(kind: Kind) -> &'static [Namespace] {
    match kind {
        Kind::Fn | Kind::Const | Kind::Static | Kind::Macro => &[Namespace::Value],
        Kind::Struct | Kind::Enum => &[Namespace::Type, Namespace::Value],
        Kind::Union | Kind::Trait | Kind::TypeAlias => &[Namespace::Type],
        Kind::Mod => &[Namespace::Value, Namespace::Type],
        Kind::Impl | Kind::Opaque | Kind::JsStaticBlock => &[],
        Kind::JsFunction
        | Kind::JsClass
        | Kind::JsMethod
        | Kind::JsGetter
        | Kind::JsSetter
        | Kind::JsField
        | Kind::JsStaticMethod
        | Kind::JsStaticField
        | Kind::JsDeclarator => &[Namespace::Value],
    }
}

fn is_value_primary(kind: Kind) -> bool {
    matches!(
        kind,
        Kind::Fn
            | Kind::Const
            | Kind::Static
            | Kind::Macro
            | Kind::JsFunction
            | Kind::JsClass
            | Kind::JsMethod
            | Kind::JsGetter
            | Kind::JsSetter
            | Kind::JsField
            | Kind::JsStaticMethod
            | Kind::JsStaticField
            | Kind::JsDeclarator
    )
}

/// `crates/svc-core/src/ids.rs` → `svc-core`. Paths outside `crates/` have no crate key.
fn crate_key(file: &RelPath) -> Option<&str> {
    file.as_str()
        .strip_prefix("crates/")
        .and_then(|rest| rest.split('/').next())
        .filter(|s| !s.is_empty())
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct EntityKindRule {
    pub node_kind: &'static str,
    pub kind: Kind,
    pub name_field: Option<&'static str>,
    pub body_field: Option<&'static str>,
    pub children_field: Option<&'static str>,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Locator {
    Itself,
    Field(&'static str),
    ChildIndex(usize),
    FieldWithKind(&'static str, &'static str),
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Visibility {
    Whole,
    AfterStmt,
    /// Fields resolve against the binder's own parent, not the scope node.
    Sub(&'static [&'static str]),
    Hoisted,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum BinderClass {
    Local,
    Generic,
    Label,
    Item,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum When {
    Always,
    ThroughBlock,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Barrier {
    pub ns: Namespace,
    pub class: BinderClass,
    pub when: When,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Role {
    Binder {
        namespace: Namespace,
        visibility: Visibility,
        locator: Locator,
    },
    Reference {
        namespace: Namespace,
    },
    Scope {
        opens: &'static [Namespace],
        barriers: &'static [Barrier],
    },
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct CommutativeRule {
    pub parent: Option<Kind>,
    pub only_child_kinds: Option<&'static [Kind]>,
    pub except_child_kinds: Option<&'static [Kind]>,
}

pub trait Lang: Send + Sync {
    fn language(&self) -> tree_sitter::Language;
    fn name(&self) -> &'static str;
    fn extensions(&self) -> &'static [&'static str];
    fn entity_kinds(&self) -> &'static [EntityKindRule];
    fn entity_name(&self, node: tree_sitter::Node<'_>, src: &[u8]) -> Option<String>;
    fn roles(
        &self,
        node: tree_sitter::Node<'_>,
        field: Option<&str>,
        src: &[u8],
        env: &Env,
    ) -> Vec<Role>;
    fn opaque_nodes(&self) -> &'static [&'static str];
    fn commutative_parents(&self) -> &'static [CommutativeRule];
    fn trivia_kinds(&self) -> &'static [&'static str];
    /// Text to wrap a lone member in so it parses, when a definition is added to or edited
    /// under a parent of `parent` kind: a JS method is not a program on its own, a Rust
    /// impl method is an item. `None` means the member parses standalone.
    fn member_shell(&self, _parent: Kind) -> Option<(&'static str, &'static str)> {
        None
    }

    /// Leaf node kinds whose text is a literal (numbers, strings, chars, booleans);
    /// canonicalisation keeps their text as `Token::Lit`.
    fn literal_kinds(&self) -> &'static [&'static str] {
        &[]
    }
    /// Override the table kind for nodes that share a grammar kind (JS getters/setters).
    fn refine_kind(&self, _node: tree_sitter::Node<'_>, _src: &[u8]) -> Option<Kind> {
        None
    }
}

pub struct Langs {
    langs: Vec<Box<dyn Lang>>,
}

impl Langs {
    pub fn new(langs: Vec<Box<dyn Lang>>) -> Self {
        Self { langs }
    }

    pub fn for_path(&self, p: &RelPath) -> Option<&dyn Lang> {
        let ext = p.extension()?;
        self.langs
            .iter()
            .find(|l| l.extensions().iter().any(|e| *e == ext))
            .map(|b| &**b)
    }

    pub fn iter(&self) -> impl Iterator<Item = &dyn Lang> {
        self.langs.iter().map(|b| &**b)
    }
}

#[derive(Clone, Debug)]
pub struct RawEntity {
    pub kind: Kind,
    pub name: String,
    pub name_range: Option<ByteRange>,
    pub item_range: ByteRange,
    pub bytes_range: ByteRange,
    pub parent_idx: Option<usize>,
    pub children: Vec<usize>,
}

#[derive(Clone, Debug, Default)]
pub struct Resolution {
    pub slots: Vec<(ByteRange, crate::ids::Slot, Namespace)>,
    pub refs: Vec<(ByteRange, crate::content::IdentRef)>,
}

